import fs from 'node:fs';
import { pathToFileURL } from 'node:url';
import { loadContent, root } from './load-content.mjs';

export function generateStudyGuide(data) {
  const { questions, labs, resources, areas, insights, outcomes, localeData, uiText } = data;
  const letter = i => String.fromCharCode(65 + i);
  const lines = [
    '# AB-620 Field Guide', '',
    '<!-- Generated by scripts/generate-study-guide.mjs. Edit static data and locale-data.js, then regenerate. -->', '',
    'Independent, unofficial study material for Microsoft Certified: AI Agent Builder Associate. No affiliation, endorsement, exam-content authenticity, accuracy guarantee or exam-success guarantee is implied.', '',
    '## Sources and scope', '',
    '90 practice questions: 45 attributed to DumpsBase, 9 Microsoft Learn-aligned additions (not official exam questions), 24 The Data Community adaptations, and 12 paraphrased courseware-derived questions.', '',
    'Original source means attribution; verification source means supporting Microsoft Learn documentation; related labs are learning associations, not origin claims. Q54 and Q55-Q90 have individual review dates and scope notes. Other entries retain topic-level references and are explicitly unreviewed in this audit. Supported means documentation supports the explanation within its stated scope, not that a live tenant was tested. Partial evidence must not be read as full confirmation.', '',
    'See [source evidence](SOURCE-EVIDENCE.md) for lookup method, reviewed sections, origin corrections and limitations. Courseware links are pinned to commit `941360e11dfa677914a00281a8255404e8c848e0` in the [Tertiary Courses repository](https://github.com/tertiarycourses/C1760-AB-620-Microsoft-Certified-AI-Agent-Builder-Associate). Original slides, PDFs and DOCX files are not copied here.', '',
    '- [Official study guide](https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/ab-620)',
    '- [AB-620T00 course](https://learn.microsoft.com/en-us/training/courses/ab-620t00)',
    '- [Microsoft Certified Associate badge reference](https://learn.microsoft.com/en-us/media/learn/certification/badges/microsoft-certified-associate-badge.svg)', '',
    '## Exam scope', '', '| Area / Bereich | Weight |', '| --- | --- |',
    ...areas.map(a => `| ${a.title} / ${localeData.de.areas[a.id].title} | ${a.weight} |`), '',
    '## How to study', '',
    'Answer first, then inspect both explanations and the source scope. The site defaults to English, supports authored German translations, and keeps product names and answer identifiers stable. Exams use separate, tab-memory-only answers, hide hints while active and freeze results on completion. Reset clears study/lab/exam progress but keeps language and theme. See README.md for storage, external requests and test commands.', '',
    'Review keeps answer feedback visible until Finish. Finish recalculates remaining weak spots (incorrect or unanswered questions), restarting with those questions or showing the completed empty state if none remain. In Learn mode, Back to first question returns to the start of the current filtered set without clearing answers.', '',
    '## Learning outcomes', '',
    ...outcomes.flatMap((o, i) => [`${i + 1}. ${o}`, `   ${localeData.de.outcomes[`outcome-${i + 1}`]}`]), '',
    '## Terminology cautions', '',
    '| Practice shorthand | Interpretation |', '| --- | --- |',
    '| Strictness / Restrict external knowledge | Check current grounding controls and configured knowledge sources; terminology and behavior vary by feature. |',
    '| Azure AD B2C | Verify current Microsoft Entra / OAuth configuration for the scenario. |',
    '| A2A polling loop | Agent delegation is not generic deterministic error handling. |',
    '| MCP for every integration | Use MCP when it is the appropriate supported tool/resource interface, not as a replacement for all APIs. |',
    '| boundary / conflict | Course-specific test category and evidence-state vocabulary, not official universal metric/status names. |', '',
    '## Complete question bank (90 questions)', '',
  ];
  for (const q of questions) {
    lines.push(`### Question ${q.id}`, '', `**Classification:** ${q.sourceType}`, `**Topic:** ${q.topic}`, `**Format:** ${q.format}`, '');
    for (const language of ['en', 'de']) {
      const localized = { ...q, ...localeData[language]?.questions?.[q.id] };
      const answer = q.format === 'matching'
        ? Object.entries(q.matches).map(([row, value]) => `${Number(row) + 1} -> ${value}`).join(', ')
        : (Array.isArray(q.answer) ? q.answer : [q.answer]).map(i => `${letter(i)}. ${localized.options[i]}`).join('; ');
      lines.push(language === 'en' ? '**English**' : '**Deutsch**', '', `> ${localized.question}`, '',
        ...localized.options.map((option, i) => q.format === 'matching' ? `- ${option}` : `- **${letter(i)}.** ${option}`), '');
      if (q.matchLabels) lines.push(...localized.matchLabels.map(label => `- ${label}`), '');
      lines.push(`**${language === 'en' ? 'Correct answer' : 'Richtige Antwort'}:** ${answer}`, '', `**${language === 'en' ? 'Explanation' : 'Deutsche Erklärung'}:** ${localized.explanation}`, '');
    }
    lines.push(`**Original source:** [${q.sourceType}](${q.originalSource})`, `**Verification source:** [Microsoft Learn](${q.verificationSource})`,
      `**Review status:** ${q.verification}${q.verifiedOn ? ` (${q.verifiedOn})` : ''}`, `**Scope:** ${q.verificationNote}`,
      `**Prüfumfang:** ${localeData.de.evidenceNotes[q.id] || localeData.de.shared[q.verificationNote]}`,
      `**Related labs:** ${q.labIds.map(id => `[${id}](#${id})`).join(', ')}`, '');
  }
  lines.push('## Course path', '', '20 paraphrased lab briefs across five days in one Contoso service-operations scenario. Checklists track local learning progress, not certification or evidence of a real deployment.', '');
  for (const lab of labs) {
    lines.push(`<a id="${lab.id}"></a>`, `### Lab ${lab.number}: ${lab.title}`, '', `Day ${lab.day} / Tag ${lab.day}`, '');
    for (const language of ['en', 'de']) {
      const l = { ...lab, ...localeData[language]?.labs?.[lab.id] };
      lines.push(`**${language === 'en' ? 'English' : 'Deutsch'}:** ${l.summary}`, '', ...l.checklist.map(s => `- [ ] ${s}`), '', `**${uiText[language].artifacts}:** ${l.artifacts.join('; ')}`, '');
    }
    lines.push(`[Original lab](${lab.sourceUrl})`, `**Status:** ${lab.verificationStatus}`, '', '**Resources / Ressourcen:**', '',
      ...resources.filter(r => r.labs.includes(lab.id)).map(r => `- [${r.title} / ${localeData.de.resources[r.id].title}](${r.url})`), '',
      `**Related questions / Verwandte Fragen:** ${lab.relatedQuestionIds.map(id => `[Q${id}](#question-${id})`).join(', ')}`, '');
  }
  lines.push('## Courseware insights', '');
  for (const insight of insights) {
    lines.push(`### ${localeData.en.insights[insight.id].title}`, '');
    for (const language of ['en', 'de']) {
      const entry = localeData[language].insights[insight.id];
      lines.push(`**${language}:** ${entry.text}`, `**Status (${language}):** ${entry.status}`, '');
    }
    lines.push(`[Microsoft Learn reference](${insight.source})`, `Related labs: ${insight.labs.join(', ')}`, '');
  }
  lines.push('As of 2026-09-06, insight claims have not been individually re-audited. Earlier inherited confirmation labels lacked per-claim evidence in this audit and have been replaced with explicit unreviewed limitations. The linked pages are references, not proof of every claim. See the individual question notes for the separate bounded source audit.', '',
    '## Disclaimer', '', 'All questions are practice adaptations, not authenticated exam questions. Documentation and previews can change. Verify current Microsoft Learn guidance and tenant behavior. Legal and privacy notices remain placeholders requiring operator details and appropriate review before publication.', '');
  return lines.join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const output = generateStudyGuide(loadContent());
  const destination = new URL('AB620.md', root);
  if (process.argv.includes('--check')) {
    if (fs.readFileSync(destination, 'utf8') !== output) { console.error('AB620.md is stale; run npm run docs:generate'); process.exitCode = 1; }
    else console.log('AB620.md matches canonical data and locales');
  } else { fs.writeFileSync(destination, output); console.log('Generated AB620.md'); }
}
